codeExamples.code:
-- Escaping a literal single quote by doubling it:
SELECT * FROM customers WHERE last_name = 'O''Brien';

-- Delimited identifier (standard double quotes) for a column
-- whose name has a space or is a reserved word:
SELECT "Order Date", "order"
FROM "Order Details";

-- MySQL uses backticks instead of double quotes:
-- SELECT `Order Date`, `order` FROM `Order Details`;
